"geb_Lure1": {
"cat": "lure",
"desc": "Popper baits are topwater lures featuring a cupped face that creates a loud &quot;popping&quot; sound and splashing action to imitate injured baitfish or surface-feeding fish. Ideal for spring and summer, they are highly effective for bass and saltwater species like Giant Trevally. Retrieve with a &quot;pop-pause&quot; technique, letting it sit to trigger explosive strikes.",
"img": "items/geb_Lure1.webp",
"name": "Popper Lure"
},
"geb_Lure2": {
"cat": "lure",
"desc": "Crankbaits are hard-bodied, diving fishing lures with bills that determine depth, used primarily for bass, walleye, and crappie by reeling them in with a consistent, fast retrieve to mimic baitfish.",
"img": "items/geb_Lure2.webp",
"name": "Purple Crankbait"
},
"geb_Lure3": {
"cat": "lure",
"desc": "Crankbaits are hard-bodied, diving fishing lures with bills that determine depth, used primarily for bass, walleye, and crappie by reeling them in with a consistent, fast retrieve to mimic baitfish.",
"img": "items/geb_Lure3.webp",
"name": "Yellow Crankbait"
},
"geb_Lure4": {
"cat": "lure",
"desc": "A square bill lure is a shallow-running, shallow-diving crankbait characterized by a flat, square-shaped plastic or circuit board lip. Designed for fishing in 1–8 feet of water, its unique bill deflects sharply off timber, rocks, and shallow cover to trigger reaction strikes. These lures often feature a wide, &quot;hunting&quot; wobble.",
"img": "items/geb_Lure4.webp",
"name": "Squarebill Lure"
},
